                                                                                                                                                                                                       
  CREATE TABLE "BASIC_DEVICE"                                                                                                                                                               
   (	"DEVICE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                   
	"REMARK" NVARCHAR2(512),                                                                                                                                                                              
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"DEVICE_CODE" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                          
	"DEVICE_NAME" NVARCHAR2(100) DEFAULT 'unknown',                                                                                                                                                       
	"IP" NVARCHAR2(100),                                                                                                                                                                                  
	"IS_ENABLE" NUMBER NOT NULL ENABLE,                                                                                                                                                                   
	"MAP_AREA_X_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                         
	"MAP_AREA_Y_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                         
	"FAB_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                
	"MANAGEMENT_EXT_ORG_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                 
	"CATEGORY_FIRST_CODE" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                  
	"CATEGORY_SECOND_CODE" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                 
	"PROJECT_ID" NUMBER,                                                                                                                                                                                  
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	 PRIMARY KEY ("DEVICE_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

